chromeicosahedroninterior.glsl:
#version 300 es
precision highp float;

uniform float time;
uniform vec2 resolution;

out vec4 fragColor;

#define TAU 6.283185307179586
#define PI 3.141592653589793

uniform int reflections;      // 2-10, number of internal mirror bounces
uniform float glowIntensity;  // 0.0-3.0, brightness of edge glow effect
uniform float chromeShift;    // 0.0-0.1, chromatic aberration strength
uniform float cameraOffset;   // 0.0-0.4, camera distance from center

// Hash functions for procedural generation
float hash(float p) {
    return fract(sin(p * 127.1) * 43758.5453);
}

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec3 hash3(vec2 p) {
    vec3 q = vec3(dot(p, vec2(127.1, 311.7)),
                  dot(p, vec2(269.5, 183.3)),
                  dot(p, vec2(419.2, 371.9)));
    return fract(sin(q) * 43758.5453);
}

// Value noise - pure math, noiseOffset enables animation when passed from main
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);

    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Golden ratio for icosahedron geometry
const float PHI = 1.618033988749895;

// Icosahedron SDF - signed distance (negative inside)
float sdIcosahedron(vec3 p, float r) {
    vec3 n = normalize(vec3(PHI, 1.0, 0.0));
    vec3 ap = abs(p);
    float a = dot(ap, n);
    float b = dot(ap, n.yzx);
    float c = dot(ap, n.zxy);
    return max(max(a, b), c) - r;
}

// Get icosahedron face normal at point
vec3 icosahedronNormal(vec3 p) {
    vec3 n = normalize(vec3(PHI, 1.0, 0.0));
    vec3 ap = abs(p);
    vec3 sp = sign(p + 1e-6);

    float a = dot(ap, n);
    float b = dot(ap, n.yzx);
    float c = dot(ap, n.zxy);

    if (a >= b && a >= c) return sp * n;
    if (b >= a && b >= c) return sp.yzx * n.yzx;
    return sp.zxy * n.zxy;
}

// Fresnel reflectance (Schlick approximation)
float fresnel(vec3 viewDir, vec3 normal, float f0) {
    float cosTheta = max(dot(-viewDir, normal), 0.0);
    return f0 + (1.0 - f0) * pow(1.0 - cosTheta, 5.0);
}

// Chrome metallic palette - t is 0-1 position, NOT time
vec3 chromePalette(float t) {
    vec3 silver = vec3(0.9, 0.92, 0.95);
    vec3 cyan = vec3(0.7, 0.9, 1.0);
    vec3 gold = vec3(1.0, 0.95, 0.85);
    vec3 blue = vec3(0.7, 0.75, 0.85);

    t = clamp(t, 0.0, 0.9999);
    float segment = t * 4.0;
    int idx = int(segment);
    float blend = segment - float(idx);

    if (idx == 0) return mix(silver, cyan, blend);
    if (idx == 1) return mix(cyan, blue, blend);
    if (idx == 2) return mix(blue, gold, blend);
    return mix(gold, silver, blend);
}

// Procedural environment for reflections
// noiseOffset passed from main for animation
vec3 proceduralEnvironment(vec3 dir, vec2 noiseOffset) {
    float theta = atan(dir.z, dir.x);
    float phi = asin(clamp(dir.y, -1.0, 1.0));

    float band = sin(theta * 3.0) * cos(phi * 2.0);
    band += noise(vec2(theta, phi) * 5.0 + noiseOffset) * 0.3;

    float palettePos = band * 0.5 + 0.5;
    vec3 col = chromePalette(palettePos);
    col *= 0.8 + 0.2 * noise(dir.xz * 8.0 + noiseOffset);

    return col;
}

// Rotation helpers
vec3 rotateY(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}

vec3 rotateX(vec3 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec3(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}

// Edge glow at grazing angles
float edgeGlow(vec3 viewDir, vec3 normal) {
    float edge = 1.0 - abs(dot(viewDir, normal));
    return pow(max(edge, 0.0), 3.0);
}

// Reflect ray inside icosahedron and accumulate color
vec3 reflectRay(vec3 dir, vec3 normal) {
    return reflect(dir, normal);
}

void main() {
    vec2 uv = gl_FragCoord.xy / resolution;
    vec2 centered = uv - 0.5;
    centered.x *= resolution.x / resolution.y;

    // ═══════════════════════════════════════════════════════════════════════════
    // LOOPING PRIMITIVES - ALL ANIMATION MUST USE THESE
    // time goes 0→1, so t goes 0→TAU, completing exactly one cycle
    // ═══════════════════════════════════════════════════════════════════════════
    float t = time * TAU;           // Converts time 0→1 to radians 0→TAU
    vec2 timeCircle = vec2(cos(t), sin(t));  // For noise sampling - traces a circle
    float pulse = 0.5 + 0.5 * sin(t);        // 0→1→0 smooth oscillation
    float wave = sin(t);                      // -1→1→-1 smooth oscillation

// ═══════════════════════════════════════════════════════════════════════════
    // MAIN EFFECT LOGIC - Chrome Icosahedron Interior
    // ═══════════════════════════════════════════════════════════════════════════

    float icoRadius = 1.0;

    // Camera orbiting inside the icosahedron - uses wave for smooth back-and-forth
    vec3 camPos = vec3(
        timeCircle.x * cameraOffset,
        wave * cameraOffset * 0.3,
        timeCircle.y * cameraOffset
    );

    // Camera look direction with gentle oscillation
    vec3 camTarget = vec3(wave * 0.1, sin(t * 2.0) * 0.05, 0.0);
    vec3 camForward = normalize(camTarget - camPos);
    vec3 camRight = normalize(cross(vec3(0.0, 1.0, 0.0), camForward));
    vec3 camUp = cross(camForward, camRight);

    // Ray direction through pixel
    vec3 rayDir = normalize(camForward + centered.x * camRight + centered.y * camUp);

    // Final accumulated color with chromatic aberration
    vec3 finalColor = vec3(0.0);

    // Trace 3 rays for chromatic aberration (R, G, B channels)
    for (int channel = 0; channel < 3; channel++) {
        float aberrationOffset = (float(channel) - 1.0) * chromeShift;
        vec3 traceDir = normalize(rayDir + camRight * aberrationOffset);
        vec3 traceOrigin = camPos;

        vec3 channelColor = vec3(0.0);
        float channelAtten = 1.0;

        // Reflection bounces inside icosahedron
        for (int bounce = 0; bounce < 10; bounce++) {
            if (bounce >= reflections) break;

            // Ray march to find icosahedron surface from inside
            float marchDist = 0.0;
            vec3 hitPos = traceOrigin;

            for (int step = 0; step < 48; step++) {
                hitPos = traceOrigin + traceDir * marchDist;
                float d = -sdIcosahedron(hitPos, icoRadius);
                if (d < 0.001) break;
                marchDist += max(d * 0.6, 0.002);
                if (marchDist > 4.0) break;
            }

            // Surface normal pointing inward
            vec3 normal = -icosahedronNormal(hitPos);

            // Fresnel - chrome is highly reflective
            float fresnelVal = fresnel(traceDir, normal, 0.85);

            // Edge glow - bright at grazing angles, pulsing
            float glow = edgeGlow(traceDir, normal);
            float pulsingGlow = glow * glowIntensity * (0.7 + 0.5 * pulse);

            // Sample procedural environment in reflection direction
            vec3 reflectDir = reflect(traceDir, normal);
            vec3 envColor = proceduralEnvironment(reflectDir, timeCircle * 0.5);

            // Accumulate environment color through attenuation
            channelColor += channelAtten * envColor * (1.0 - fresnelVal) * 0.4;

            // Add edge glow with animated palette position
            float palettePos = 0.5 + 0.3 * sin(t + float(bounce) * 0.8);
            vec3 glowCol = chromePalette(palettePos);
            channelColor += channelAtten * glowCol * pulsingGlow;

            // Attenuate for next bounce
            channelAtten *= fresnelVal * 0.88;

            // Set up next bounce
            traceDir = reflectDir;
            traceOrigin = hitPos + traceDir * 0.01;
        }

        // Final environment contribution after all bounces
        vec3 finalEnv = proceduralEnvironment(traceDir, timeCircle * 0.5);
        channelColor += channelAtten * finalEnv;

        // Assign to appropriate color channel
        if (channel == 0) finalColor.r = channelColor.r;
        else if (channel == 1) finalColor.g = channelColor.g;
        else finalColor.b = channelColor.b;
    }

    // Add central bright spot with animated intensity
    float centerDist = length(centered);
    float centerGlow = exp(-centerDist * 4.0) * 0.3 * (0.8 + 0.4 * pulse);
    finalColor += chromePalette(pulse) * centerGlow;

    // Subtle vignette
    float vignette = 1.0 - centerDist * 0.4;
    finalColor *= vignette;

    // Filmic tone mapping
    finalColor = finalColor / (1.0 + finalColor * 0.5);

    // Output color
    vec3 color = pow(max(finalColor, vec3(0.0)), vec3(0.92));

fragColor = vec4(color, 1.0);
}
